var buf = Solution.EncodeFrame("x").Concat(Solution.EncodeFrame("yy")).ToArray();
var partial = buf.Concat(new byte[] { 0, 0, 0 }).ToArray();   // truncated third frame
var r = Solution.DecodeStreamSafe(partial);
Cj.Eq(string.Join("|", r), "x|yy", "complete frames only; partial ignored");
